#nullable enable // autogenerated

using MVZ2Logic.Resources;
using MVZ2Logic.UI;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2Logic.Models.Components
{
    [RequireComponent(typeof(SpriteRendererResolver))]
    public class ModelPropertySpriteSetterReference : ModelComponent
    {
        public override void UpdateFrame(float deltaTime)
        {
            var reference = GetSpriteReference();
            if (reference != beforeReference || (Application.isEditor && !Application.isPlaying))
            {
                beforeReference = reference;
                var sprite = Global.Resources?.GetSprite(reference);
                Renderer.SetSprite(sprite);
            }
        }
        public SpriteReference? GetSpriteReference()
        {
            if (string.IsNullOrEmpty(propertyName))
                return null;
            return Model.GetProperty<SpriteReference>(propertyName);
        }
        private SpriteRendererResolver Renderer
        {
            get
            {
                if (!sprRenderer.Exists())
                {
                    sprRenderer = GetComponent<SpriteRendererResolver>();
                }
                return sprRenderer;
            }
        }
        private SpriteRendererResolver? sprRenderer;
        private SpriteReference? beforeReference;
        public string? propertyName;
    }
}